style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Background img */
    body, html {
        background: url("https://i.pinimg.com/736x/95/b0/3d/95b03da2b2487ee7553f8ea5e0e294e9.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: #912f19 !important; /* fallback color */
        font-family: 'Gloria+Hallelujah', sans-serif !important;
   }

    /* Font */
    @font-face {
        font-family: 'Gloria Hallelujah';
      src: url('https://fonts.gstatic.com/s/gloriahallelujah/v20/caJEX4TNrG5MT2PBr7EAKsU3SzWQ6RZFkv0.woff2') format('woff2');
}

    /* General */
    .container-main, 
    .game-page, 
    .section-content, 
    .content,
    .content-container,
    .profile-container,
    .games-container,
    .navbar, 
    #container-main, 
    #navigation, 
    #header,
    .menu-bar,
    .content {
        background: rgba(255, 255, 255, 0.4) !important; /* semitransparent white */
        backdrop-filter: blur(10px) saturate(120%);
        border-radius: 12px !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
    }

    /* Gui colors */
    .navbar, #navigation, #header {
        background-color: rgba(191, 97, 90, 0.5) !important; /* soft red */
        backdrop-filter: blur(2px) saturate(120%);
    }

    /* Text color */
    body, html, .text, .content-text, .game-name, .profile-username, .section-title {
        color: #333 !important; /* dark text */
    }

    /* Buttons */
    button, .btn, .action-button, .btn-control-sm {
        background-color: rgba(214, 195, 118, 0.7) !important; /* soft yellow btns */
        color: #000 !important;
        border: none !important;
        border-radius: 8px !important;
    }

    button:hover, .btn:hover {
        background-color: rgba(135, 125, 85, 0.8) !important; /* slightly dull on hover */
    }
}
